"""MCP server exposing this repository's verified research tools (generated by TerraKernel).

Run from the repository root:  uv run python tools/mcp_server.py   (stdio transport)

Series inputs are passed as references instead of raw arrays:
  "<dataset>"            the only value column of a dataset (see list_datasets)
  "<dataset>.<column>"   a specific column
  "param:<name>"         a time-varying parameter, evaluated on the aligned timestamps
All dataset references in one call (plus any listed in ``align_with``) are aligned on a
common valid sample first, as the repository's conventions require.
"""

from __future__ import annotations

import importlib
import inspect
import json
import os
import sys
from pathlib import Path
from typing import Any

REPO_ROOT = Path(os.environ.get("CLAUDE_PROJECT_DIR") or Path(__file__).resolve().parents[1])
sys.path.insert(0, str(REPO_ROOT / "tools"))

import pandas as pd  # noqa: E402
import research_tools as rt  # noqa: E402
from mcp.server import MCPServer  # noqa: E402
from mcp.types import ToolAnnotations  # noqa: E402

REGISTRY = json.loads((REPO_ROOT / "tools" / "research_tools" / "registry.json").read_text())
server = MCPServer(REGISTRY.get("name", "research-tools"), instructions=REGISTRY.get("instructions", ""))
READ_ONLY = ToolAnnotations(read_only_hint=True, open_world_hint=False)


def _resolve(refs: dict[str, str], align_with: list[str]) -> tuple[dict[str, pd.Series], dict[str, Any]]:
    data = {k: v for k, v in refs.items() if not v.startswith("param:")}
    loaded = {}
    for key, ref in {**data, **{f"_align_{i}": r for i, r in enumerate(align_with)}}.items():
        name, _, column = ref.partition(".")
        loaded[key] = rt.load_series(name, column or None)
    if loaded:
        frame = rt.common_valid_sample(**loaded)
        series = {k: frame[k] for k in data}
        info = frame.attrs.get("terrakernel", {})
        index = frame.index
    else:
        series, info, index = {}, {}, None
    for key, ref in refs.items():
        if ref.startswith("param:"):
            if index is None:
                raise ValueError("a parameter needs at least one dataset input to define the timestamps")
            series[key] = rt.parameter_series(ref.split(":", 1)[1], index)
    return series, info


def _make_tool(entry: dict[str, Any]):
    module = importlib.import_module(entry["module"])
    fn = getattr(module, entry["name"])
    params = []
    for inp in entry["inputs"]:
        ann = str if inp["kind"] in ("series", "string") else float
        params.append(inspect.Parameter(inp["name"], inspect.Parameter.KEYWORD_ONLY, annotation=ann))
    params.append(inspect.Parameter("align_with", inspect.Parameter.KEYWORD_ONLY, default=[], annotation=list[str]))

    def tool(**kwargs: Any) -> dict[str, Any]:
        align_with = kwargs.pop("align_with", []) or []
        refs = {i["name"]: kwargs[i["name"]] for i in entry["inputs"] if i["kind"] == "series"}
        series, info = _resolve(refs, align_with)
        args = {i["name"]: (series[i["name"]] if i["kind"] == "series" else kwargs[i["name"]]) for i in entry["inputs"]}
        value = fn(**args)
        if isinstance(value, pd.Series):
            value = {"length": len(value), "head": value.head(5).to_dict()}
        return {"tool": entry["name"], "value": value, "unit": entry.get("output_unit"),
                "inputs": kwargs | {"align_with": align_with}, "sample": info}

    tool.__signature__ = inspect.Signature(params, return_annotation=dict[str, Any])
    tool.__annotations__ = {p.name: p.annotation for p in params} | {"return": dict[str, Any]}
    tool.__name__ = entry["name"]
    desc = entry.get("description", "") + "\n\nInputs:\n" + "\n".join(
        f"- {i['name']} ({i['kind']}{', ' + i['unit'] if i.get('unit') else ''}): {i['description']}"
        for i in entry["inputs"]) + "\nSeries inputs are references such as 'dataset', 'dataset.column' or 'param:name'."
    server.add_tool(tool, name=entry["name"], description=desc, annotations=READ_ONLY)


@server.tool(annotations=READ_ONLY)
def list_datasets() -> list[str]:
    """List the configured datasets of this repository."""
    return rt.list_datasets()


@server.tool(annotations=READ_ONLY)
def dataset_info(name: str) -> dict[str, Any]:
    """Show a dataset's file, columns, units, timestamp convention, provenance and open issues."""
    return rt.dataset_info(name)


@server.tool(annotations=READ_ONLY)
def describe_tools() -> list[dict[str, Any]]:
    """List the repository's tools with their verification status and knowledge references."""
    return [{k: t.get(k) for k in ("name", "description", "status", "strategy", "output_unit", "knowledge")}
            for t in REGISTRY.get("tools", [])]


for _entry in REGISTRY.get("tools", []):
    if _entry.get("status") == "verified":
        _make_tool(_entry)


if __name__ == "__main__":
    server.run()
